//go:build ignore
package main
import("encoding/json";"os";"reflect";"strings";"github.com/Tencent/WeKnora/internal/types";"github.com/Tencent/WeKnora/internal/application/service")
func schema(t reflect.Type)map[string]interface{}{if t.Kind()==reflect.Pointer{return map[string]interface{}{"kind":"pointer","elem":schema(t.Elem())}};out:=map[string]interface{}{"kind":t.Kind().String()};switch t.Kind(){case reflect.Struct:p:=[]interface{}{};for i:=0;i<t.NumField();i++{f:=t.Field(i);tag:=strings.Split(f.Tag.Get("json"),",");name:=tag[0];if name=="-"{continue};if name==""{name=f.Name};omit:=false;for _,s:=range tag[1:]{if s=="omitempty"{omit=true}};p=append(p,map[string]interface{}{"name":name,"omitempty":omit,"schema":schema(f.Type)})};out["fields"]=p;case reflect.Slice,reflect.Array:out["elem"]=schema(t.Elem());case reflect.Map:out["elem"]=schema(t.Elem())};return out}
func effective(e types.EffectiveProcessConfig)map[string]interface{}{return map[string]interface{}{"summary_enabled":e.SummaryEnabled,"chunking_config":e.ChunkingConfig,"enable_multimodel":e.EnableMultimodel,"vlm_config":e.VLMConfig,"asr_config":e.ASRConfig,"question_generation_config":e.QuestionGenerationConfig,"graph_enabled":e.GraphEnabled,"image_attrs_enabled":e.ImageAttrsEnabled,"image_actions":e.ImageActions,"extract_config":e.ExtractConfig}}
func main(){if len(os.Args)>1&&os.Args[1]=="schema"{json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"chunking":schema(reflect.TypeFor[types.ChunkingConfig]()),"vlm":schema(reflect.TypeFor[types.VLMConfig]()),"asr":schema(reflect.TypeFor[types.ASRConfig]()),"question":schema(reflect.TypeFor[types.QuestionGenerationConfig]()),"extract":schema(reflect.TypeFor[types.ExtractConfig]()),"image_actions":schema(reflect.TypeFor[types.ImageActionsConfig]()),"overrides":schema(reflect.TypeFor[types.KnowledgeProcessOverrides]())});return}
kbInputs:=[]string{`{}`,`{"chunking_config":{"chunk_size":512,"chunk_overlap":80,"separators":["\n\n","。"],"enable_parent_child":true,"parent_chunk_size":4096,"child_chunk_size":384,"strategy":"auto","languages":["zh"],"parser_engine_rules":[{"file_types":["xlsx"],"engine":"builtin","xlsx_first_row_as_header":true}]},"vlm_config":{"enabled":true,"model_id":"vlm","description_language":"zh","custom_instructions":"base image"},"asr_config":{"enabled":true,"model_id":"asr","language":"zh"},"question_generation_config":{"enabled":true,"question_count":6,"custom_instructions":"base questions"},"extract_config":{"enabled":true,"text":"base text","tags":["tag"],"custom_instructions":"base extract"},"indexing_strategy":{"graph_enabled":true},"image_processing_config":{"image_attrs_enabled":true}}`,`{"vlm_config":{"model_name":"legacy","base_url":"https://vlm.example.test","api_key":"secret"},"extract_config":{"enabled":true},"indexing_strategy":{"graph_enabled":false},"image_processing_config":{"image_actions":{"ocr":{"on":[{"prop":"contain.text","is":"none"}],"on_unobserved":false}}}}`}
overrides:=[]string{`null`,`{}`,`{"summary_enabled":false,"enable_multimodel":false,"graph_enabled":false,"image_attrs_enabled":false}`,`{"summary_enabled":true,"enable_multimodel":true,"graph_enabled":true,"image_attrs_enabled":true}`,`{"chunking_config":{}}`,`{"chunking_config":{"chunk_size":128,"chunk_overlap":0,"enable_parent_child":false,"strategy":"heading","table_metadata_instructions":"new table"}}`,`{"chunking_config":{"chunk_size":-1,"chunk_overlap":-2,"parent_chunk_size":-3,"child_chunk_size":-4,"token_limit":-5,"separators":[],"languages":[]}}`,`{"chunking_config":{"separators":["|"],"languages":["de","en"],"parser_engine_rules":[{"file_types":["pdf"],"engine":"mineru"}]},"parser_engine_rules":[{"file_types":["docx"],"engine":"markitdown"}]}`,`{"vlm_config":{}}`,`{"vlm_config":{"enabled":true,"model_id":"other"}}`,`{"vlm_config":{"description_language":"en","custom_instructions":"new image"}}`,`{"asr_config":{}}`,`{"asr_config":{"enabled":true,"model_id":"other","language":"en"}}`,`{"question_generation_config":{}}`,`{"question_generation_config":{"enabled":true,"question_count":9}}`,`{"question_generation_config":{"custom_instructions":"new questions"}}`,`{"extract_config":{}}`,`{"extract_config":{"enabled":true}}`,`{"extract_config":{"enabled":false,"text":"new text","tags":["a"],"custom_instructions":"new extract"}}`,`{"image_actions":{}}`,`{"image_actions":{"ocr":{"on_unobserved":false}}}`,`{"image_actions":{"ocr":{"on":[{"prop":"kind","is":"chart"}],"on_unobserved":false}}}`,`{"graph_enabled":true,"extract_config":{"enabled":false}}`,`{"enable_multimodel":null,"vlm_config":null,"asr_config":null,"chunking_config":null,"parser_engine_rules":[],"parser_engine_overrides":{"pdf_force_scanned":"true"}}`}
rows:=[]interface{}{};for _,k:=range kbInputs{for _,o:=range overrides{var kb types.KnowledgeBase;var override *types.KnowledgeProcessOverrides;if err:=json.Unmarshal([]byte(k),&kb);err!=nil{panic(err)};if err:=json.Unmarshal([]byte(o),&override);err!=nil{panic(err)};rows=append(rows,map[string]interface{}{"kb":json.RawMessage(k),"overrides":json.RawMessage(o),"effective":effective(service.ResolveProcessConfig(&kb,override))})}};json.NewEncoder(os.Stdout).Encode(rows)}
